python - <<'PY'
from semver import VersionInfo

for version in (VersionInfo(1, 2, 3, 'rc.1', 'build.4'), VersionInfo(0)):
    expected = (version.major, version.minor, version.patch, version.prerelease, version.build)
    assert version.to_tuple() == expected
    assert isinstance(version.to_tuple(), tuple)
    assert version.to_dict() == dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), expected))
    assert isinstance(version.to_dict(), dict)
    result = version.to_dict()
    result['major'] = 99
    assert version.major == expected[0]
    for index in range(-5, 5):
        assert version[index] == expected[index]
    for start in (None, -7, -1, 0, 2, 7):
        for stop in (None, -7, -1, 0, 3, 7):
            for step in (None, -2, -1, 1, 2):
                index = slice(start, stop, step)
                assert version[index] == expected[index]
    for index, error in ((5, IndexError), (-6, IndexError), ('major', TypeError), (1.0, TypeError), (slice(None, None, 0), ValueError)):
        try:
            version[index]
        except error:
            pass
        else:
            raise AssertionError('Expected %s for %r' % (error, index))
print('Accessor and indexing checks passed')
PY
